import { FOOD_PHOTO_BY_NAME } from "@/lib/foodImages";

/** The coffee photos from the JavaGem Figma file (public/figma/photos), for coffee drinks with no dish photo of their own. */
const COFFEE_PHOTOS = ["p2", "p3", "p4", "p5"];

/**
 * A photo for a menu item, or null. Dish photos come from `FOOD_PHOTO_BY_NAME` (generated by
 * scripts/build-food-images.mjs, matched on the lowercase item name). Items without one, such as a
 * dish an admin adds later, show a lettered tile instead of a misleading picture.
 */
export function menuPhoto(name: string): string | null {
  const known = FOOD_PHOTO_BY_NAME[name.trim().toLowerCase()];
  if (known) return known;
  if (!/coffee|latte|mocha|espresso|cappuccino/i.test(name)) return null;
  let hash = 0;
  for (const ch of name) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  return `/figma/photos/${COFFEE_PHOTOS[hash % COFFEE_PHOTOS.length]}.jpg`;
}
